SELECT
c.cart_item_id,
c.product_id,
c.username
FROM tbl_cart c
JOIN tbl_cart_item_options cio ON c.cart_item_id = cio.cart_item_id
WHERE c.username = #{username}
AND c.product_id = #{productId}
AND cio.option_id = #{optionId}
LIMIT 1

mapper.update:
UPDATE tbl_cart_item_options
SET quantity = quantity + #{quantity},
updated_at = NOW()
WHERE cart_item_id = #{cartItemId}
AND option_id = #{optionId}

